window.TADABBUR_HAQQA = {"_meta":{"description":"تدبّر سورة الحاقّة (٦٩)، وسورةٌ مكّيّةٌ. محورُها تقريرُ القيامةِ (الحاقّة) وأهوالِها، وذكرُ مصارعِ الأممِ المكذّبة (ثمودَ وعادٍ وفرعونَ والمؤتفكات) عبرةً، ونعمةِ النجاةِ في السفينة، ومشهدِ النفخِ في الصورِ وانشقاقِ السماءِ وحملِ العرش، وعرضِ الأعمالِ وأخذِ الكتبِ بالأيمانِ والشمائل، وجزاءِ الفريقين، وتعظيمِ القرآنِ وتنزيهِ النبيِّ عن قولِ الشعرِ والكهانة، وأنه تنزيلٌ من ربِّ العالمين. فيها «الحاقة ما الحاقة»، و«فأما من أوتي كتابه بيمينه»، و«كلوا واشربوا هنيئا بما أسلفتم في الأيام الخالية»، و«إنه لقول رسول كريم»، و«وإنه لحق اليقين».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":69,"name":"الحاقة","total_ayahs":52,"audio":[1,4,11,13,19,24,25,30,48,52],"passages":[{"title":"الحاقّةُ ومصارعُ الأممِ المكذّبة","range":[1,10],"theme":"تقريرُ القيامةِ باسمِها المهيب «الحاقة ما الحاقة وما أدراك ما الحاقة»، وتكذيبِ ثمودَ وعادٍ بالقارعة، وعقوبتِهما بالطاغيةِ والريحِ الصرصرِ العاتيةِ «كأنهم أعجاز نخل خاوية»، وفرعونَ ومن قبله والمؤتفكاتِ بالخاطئة «فعصوا رسول ربهم فأخذهم أخذة رابية»","verses":[{"n":1,"reflection":{"text":"«الحاقة»: الحاقّةُ (القيامةُ التي تحقّ فيها الأمورُ وتقع فيها الجزاء)؛ ففي هذا تقريرُ القيامةِ باسمِها المهيب؛ فأيقن بالقيامةِ التي تحقّ فيها الأعمالُ واستعدّ لها، فالقيامةُ حاقّةٌ واقعة، فاعمل لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالقيامةِ والاستعدادُ لها."},"action":{"text":"تأمّل اسمَ القيامة: الحاقّةُ، أي القيامةُ التي تحقّ (تجب وتقع لا محالة)، وتحقّ فيها الأمورُ والجزاءُ فيتبيّن المحقُّ من المبطل، أو التي تُحاقّ كلَّ إنسانٍ بعمله «الحاقة»؛ ففي هذا افتتاحُ السورةِ بذكرِ القيامةِ باسمِها المهيبِ (الحاقّة) تعظيمًا لشأنها؛ فالقيامةُ حقٌّ واقعٌ تحقّ فيه الأعمالُ والجزاء؛ فأيقن أنت بالقيامةِ التي تحقّ فيها الأعمالُ ويقع فيها الجزاء، واستعدّ لها؛ إنّ الساعةَ آتيةٌ لا ريبَ فيها؛ الحاقّة ما الحاقّة؛ القارعةُ ما القارعة؛ فالقيامةُ حاقّةٌ واقعةٌ لا شكَّ فيها، تحقّ فيها الأعمالُ والجزاء؛ فأيقن بها، واستعدّ لها بالإيمانِ والعملِ الصالح؛ فمن أيقن بها واستعدّ نجا، ومن أنكرها أو غفل خسر؛ فاجعل اليقينَ بالقيامةِ والاستعدادَ لها دأبك."}},{"n":2,"reflection":{"text":"«ما الحاقة»: ما الحاقّةُ؟ استفهامُ تعظيمٍ لشأنها وتهويلٍ لأمرها؛ ففي هذا تعظيمُ شأنِ القيامة؛ فعظّم شأنَ القيامةِ في قلبك واستعدّ لها، فالقيامةُ عظيمةُ الشأن، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ شأنِ القيامةِ في القلب، والاستعدادُ لها."},"action":{"text":"تأمّل تعظيمَ شأنها: ما الحاقّةُ؟، استفهامٌ للتعظيمِ والتفخيمِ والتهويل، أي ما أعظمَ شأنَها وأهولَ أمرها! «ما الحاقة»؛ ففي هذا تعظيمُ شأنِ القيامةِ وتهويلُ أمرها بصيغةِ الاستفهام؛ فشأنها عظيمٌ يفوق الوصف؛ فعظّم أنت شأنَ القيامةِ في قلبك، واستعدّ لها بالعملِ الصالح؛ القارعةُ ما القارعة؛ الحاقّةُ ما الحاقّة؛ وما أدراك ما يومُ الدين؛ فالقيامةُ عظيمةُ الشأنِ مهولةُ الأمر؛ فعظّم شأنها، واستحضر هولها، واستعدّ لها؛ فمن عظّم شأنها واستعدّ نجا، ومن استهان بها خسر؛ فاجعل تعظيمَ شأنِ القيامةِ في القلبِ والاستعدادَ لها دأبك."}},{"n":3,"reflection":{"text":"«وما أدراك ما الحاقة»، وأيُّ شيءٍ أعلمك ما الحاقّة؟ زيادةٌ في تعظيمِ شأنها وأنها فوق ما يُدرَك؛ ففي هذا بيانُ أنّ هولَ القيامةِ يفوق التصوّر؛ فأيقن بأنّ هولَ القيامةِ أعظمُ ممّا تتصوّر واستعدّ له، فهولُ القيامةِ يفوق الإدراك، فاعمل لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ هولَ القيامةِ يفوق التصوّر، والاستعدادُ له."},"action":{"text":"تأمّل أنّ هولها يفوق الإدراك: وما أدراك، أي وأيُّ شيءٍ أعلمك يا محمد، ما الحاقّة؟ أي إنّ شأنها أعظمُ وأهولُ من أن يُدرِكه العقلُ أو يبلغه الوصف «وما أدراك ما الحاقة»؛ ففي هذا زيادةٌ في تعظيمِ شأنِ القيامةِ وتهويلها، وبيانُ أنّ هولها يفوق التصوّرَ والإدراك؛ فهولها أعظمُ ممّا يُتصوَّر؛ فأيقن أنت بأنّ هولَ القيامةِ أعظمُ ممّا تتخيّل، واستعدّ له؛ وما أدراك ما يومُ الدين ثم ما أدراك ما يومُ الدين؛ يومَ ترونها تذهل كلُّ مرضعةٍ عمّا أرضعت؛ فهولُ القيامةِ يفوق الإدراكَ والوصف؛ فأيقن به، واستحضره، واستعدّ له بالعملِ الصالحِ والتقوى؛ فمن أيقن بهوله واستعدّ نجا، ومن استهان به خسر؛ فاجعل إدراكَ أنّ هولَ القيامةِ يفوق التصوّرَ والاستعدادَ له دأبك."}},{"n":4,"reflection":{"text":"«كذبت ثمود وعاد بالقارعة»: كذّبت ثمودُ وعادٌ بالقارعةِ (القيامةِ التي تقرع القلوبَ بأهوالها)؛ ففي هذا بيانُ تكذيبِ الأممِ بالقيامة؛ فلا تكذّب بالقيامةِ فتهلك كما هلكوا، فتكذيبُ القيامةِ سبيلُ الهلاك، فصدّق بها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ بالقيامة، والحذرُ من تكذيبها."},"action":{"text":"تأمّل تكذيبَ الأمم: كذّبت ثمودُ (قومُ صالح) وعادٌ (قومُ هود) بالقارعةِ، أي القيامةِ التي تقرع القلوبَ والأسماعَ بأهوالها، وتقرع الأعداءَ بالعذاب «كذبت ثمود وعاد بالقارعة»؛ ففي هذا بيانُ أنّ ثمودَ وعادًا كذّبوا بالقيامة، تمهيدًا لذكرِ عقوبتهم عبرةً؛ فتكذيبُ القيامةِ سببُ هلاكهم؛ فلا تكذّب أنت بالقيامةِ فتهلك كما هلكوا؛ القارعةُ ما القارعة؛ كذّبت قبلهم قومُ نوحٍ وعادٌ وثمود؛ كلٌّ كذّب الرسلَ فحقّ وعيد؛ فتكذيبُ القيامةِ سبيلُ الهلاكِ كما هلك المكذّبون؛ فصدّق بالقيامةِ وأيقن بها، ولا تكذّب؛ فمن صدّق بالقيامةِ نجا، ومن كذّب بها هلك؛ فاجعل التصديقَ بالقيامةِ والحذرَ من تكذيبها دأبك."}},{"n":5,"reflection":{"text":"«فأما ثمود فأهلكوا بالطاغية»: فأمّا ثمودُ فأُهلِكوا بالصيحةِ المجاوزةِ للحدّ (أو بطغيانهم)؛ ففي هذا بيانُ عقوبةِ ثمود؛ فاعتبر بعقوبةِ ثمودَ ولا تسلك سبيلهم، فعاقبةُ التكذيبِ الهلاك، فاتّعظ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعقوبةِ ثمود، والحذرُ من سبيلهم."},"action":{"text":"تأمّل عقوبةَ ثمود: فأمّا ثمودُ فأُهلِكوا بالطاغيةِ، أي بالصيحةِ الطاغيةِ المجاوزةِ للحدِّ في الشدّة (صيحةِ جبريلَ التي أهلكتهم)، أو بسببِ طغيانهم «فأما ثمود فأهلكوا بالطاغية»؛ ففي هذا بيانُ عقوبةِ ثمودَ بالصيحةِ الطاغيةِ جزاءَ تكذيبهم وطغيانهم؛ فأُهلِكوا بصيحةٍ واحدة؛ فاعتبر أنت بعقوبةِ ثمودَ ولا تسلك سبيلهم في التكذيبِ والطغيان؛ فأخذتهم الصيحةُ فأصبحوا في ديارهم جاثمين؛ إنا أرسلنا عليهم صيحةً واحدةً فكانوا كهشيمِ المحتظِر؛ فعاقبةُ التكذيبِ والطغيانِ الهلاكُ بالصيحةِ الطاغية؛ فاتّعظ بها، واجتنب التكذيبَ والطغيان؛ فمن اتّعظ نجا، ومن سلك سبيلهم هلك؛ فاجعل الاعتبارَ بعقوبةِ ثمودَ والحذرَ من سبيلهم دأبك."}},{"n":6,"reflection":{"text":"«وأما عاد فأهلكوا بريح صرصر عاتية»، وأمّا عادٌ فأُهلِكوا بريحٍ شديدةِ البردِ والصوتِ عاتيةٍ (متجاوزةٍ الحدّ)؛ ففي هذا بيانُ عقوبةِ عاد؛ فاعتبر بعقوبةِ عادٍ ولا تتكبّر كما تكبّروا، فالتكبّرُ والتكذيبُ سبيلُ الهلاك، فاتّعظ وتواضع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعقوبةِ عاد، والحذرُ من التكبّرِ والتكذيب."},"action":{"text":"تأمّل عقوبةَ عاد: وأمّا عادٌ فأُهلِكوا بريحٍ صرصرٍ، أي شديدةِ البردِ والصوت، أو شديدةِ الهبوب؛ عاتيةٍ، أي متجاوزةٍ الحدَّ في الشدّةِ والقوّة، عتت على خزّانها فلم تُطِعهم «وأما عاد فأهلكوا بريح صرصر عاتية»؛ ففي هذا بيانُ عقوبةِ عادٍ بالريحِ الصرصرِ العاتيةِ جزاءَ تكذيبهم وتكبّرهم (إذ قالوا: من أشدُّ منّا قوّة)؛ فأُهلِكوا بالريح؛ فاعتبر أنت بعقوبةِ عادٍ ولا تتكبّر ولا تكذّب؛ فأمّا عادٌ فاستكبروا في الأرضِ بغيرِ الحقّ... فأرسلنا عليهم ريحًا صرصرًا في أيّامٍ نحسات؛ ريحًا صرصرًا في يومِ نحسٍ مستمر؛ فعاقبةُ التكبّرِ والتكذيبِ الهلاكُ بالريحِ العاتية؛ فاتّعظ بها، وتواضع، واجتنب التكذيب؛ فمن اتّعظ وتواضع نجا، ومن تكبّر وكذّب هلك؛ فاجعل الاعتبارَ بعقوبةِ عادٍ والحذرَ من التكبّرِ والتكذيبِ دأبك."}},{"n":7,"reflection":{"text":"«سخرها عليهم سبع ليال وثمانية أيام حسوما فترى القوم فيها صرعى كأنهم أعجاز نخل خاوية»: سلّط الريحَ عليهم سبعَ ليالٍ وثمانيةَ أيّامٍ متتابعةٍ، فترى القومَ صرعى كأنهم جذوعُ نخلٍ ساقطةٍ خاوية؛ ففي هذا تصويرُ هلاكِ عادٍ التامّ؛ فاعتبر بهلاكِ الأقوياءِ الجبابرةِ في لحظة، فقوّةُ العبدِ لا تُغني عن قدرةِ الله، فتواضع واتّعظ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بهلاكِ الأقوياء، والتواضعُ لقدرةِ الله."},"action":{"text":"تأمّل هلاكَ عادٍ التامّ: سخّرها (الريحَ) عليهم سبعَ ليالٍ وثمانيةَ أيّامٍ حسومًا، أي متتابعةٍ متوالية، تحسمهم وتستأصلهم؛ فترى القومَ فيها صرعى (موتى مطروحين على الأرض)؛ كأنهم أعجازُ نخلٍ (أصولُ نخلٍ ساقطة) خاويةٍ (فارغةٍ باليةٍ لا شيءَ فيها) «فترى القوم فيها صرعى كأنهم أعجاز نخل خاوية»؛ ففي هذا تصويرُ هلاكِ عادٍ الأقوياءِ الجبابرةِ هلاكًا تامًّا بالريحِ في أيّامٍ متتابعة، حتى صاروا كجذوعِ النخلِ الساقطةِ الخاوية؛ فقوّتهم لم تُغنِ عنهم شيئًا؛ فاعتبر أنت بهلاكِ الأقوياءِ الجبابرةِ في لحظة، فقوّةُ العبدِ لا تُغني عن قدرةِ الله؛ فهل ترى لهم من باقية؛ كأنهم أعجازُ نخلٍ منقعر؛ فأهلكوا فما بقيَ منهم أحد؛ فقوّةُ الجبابرةِ لا تُغني عن عذابِ الله؛ فتواضع لقدرةِ الله، واتّعظ بهلاكِ الأقوياء، ولا تغترّ بقوّة؛ فمن اتّعظ وتواضع نجا، ومن اغترّ بقوّته هلك؛ فاجعل الاعتبارَ بهلاكِ الأقوياءِ والتواضعَ لقدرةِ الله دأبك."}},{"n":8,"reflection":{"text":"«فهل ترى لهم من باقية»: فهل ترى لهم من نفسٍ باقيةٍ أو أثرٍ باق؟ ففي هذا بيانُ استئصالِ عادٍ بالكلّيّة؛ فاعتبر بأنّ الظالمين يُستأصَلون فلا يبقى لهم أثر، فعاقبةُ الظالمين الفناء، فلا تركن إليهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ باستئصالِ الظالمين، وعدمُ الركونِ إليهم."},"action":{"text":"تأمّل استئصالَ عاد: فهل ترى لهم من باقيةٍ، أي فهل ترى لعادٍ من نفسٍ باقيةٍ حيّة، أو بقيّةٍ وأثرٍ باق؟ لا، بل استُؤصِلوا جميعًا فلم يبقَ منهم أحد «فهل ترى لهم من باقية»؛ ففي هذا بيانُ أنّ عادًا استُؤصِلوا بالكلّيّةِ فلم تبقَ لهم باقيةٌ ولا أثر؛ فأُبيدوا عن آخرهم؛ فاعتبر أنت بأنّ الظالمين المكذّبين يُستأصَلون فلا يبقى لهم أثر؛ فقُطِع دابرُ القومِ الذين ظلموا؛ فأصبحوا لا يُرى إلا مساكنهم؛ فهل تُحِسّ منهم من أحدٍ أو تسمع لهم ركزًا؛ فعاقبةُ الظالمين الاستئصالُ والفناء؛ فاعتبر بها، ولا تركن إلى الظالمين ولا تسلك سبيلهم؛ فمن اعتبر واجتنب الظلمَ نجا، ومن ركن إليهم أو ظلم هلك؛ فاجعل الاعتبارَ باستئصالِ الظالمين وعدمَ الركونِ إليهم دأبك."}},{"n":9,"reflection":{"text":"«وجاء فرعون ومن قبله والمؤتفكات بالخاطئة»، وجاء فرعونُ ومن قبله (من الأمم) والمؤتفكاتُ (قرى قومِ لوطٍ المنقلبة) بالفعلةِ الخاطئةِ (الكفرِ والمعاصي)؛ ففي هذا بيانُ اشتراكِ الأممِ في الخطيئةِ الموجبةِ للعقوبة؛ فاجتنب الخطايا الموجبةَ للهلاك، فالخطايا سبيلُ العقوبة، فاجتنبها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الخطايا الموجبةِ للعقوبة، والاتّعاظُ بالأمم."},"action":{"text":"تأمّل خطايا الأمم: وجاء فرعونُ (وقومه) ومن قبله (من الأممِ المكذّبة) والمؤتفكاتُ، أي قرى قومِ لوطٍ التي ائتفكت (انقلبت بهم فجُعِل عاليها سافلها)؛ بالخاطئةِ، أي بالفعلةِ الخاطئةِ العظيمة (الكفرِ والشركِ والمعاصي) «وجاء فرعون ومن قبله والمؤتفكات بالخاطئة»؛ ففي هذا بيانُ أنّ فرعونَ ومن قبله والمؤتفكاتِ جاؤوا بالخطيئةِ العظيمةِ الموجبةِ للعقوبة؛ فاشتركوا في الخطيئةِ فاشتركوا في العقوبة؛ فاجتنب أنت الخطايا الموجبةَ للهلاك (الكفرَ والشركَ والمعاصي)؛ فكلًّا أخذنا بذنبه؛ وأخذنا الذين ظلموا بعذابٍ بئيسٍ بما كانوا يفسقون؛ فالخطايا العظيمةُ سبيلُ العقوبةِ والهلاك؛ فاجتنبها، واتّعظ بمصارعِ الأممِ الخاطئة؛ فمن اجتنب الخطايا نجا، ومن ارتكبها هلك؛ فاجعل اجتنابَ الخطايا الموجبةِ للعقوبةِ والاتّعاظَ بالأممِ دأبك."}},{"n":10,"reflection":{"text":"«فعصوا رسول ربهم فأخذهم أخذة رابية»: فعصوا رسولَ ربّهم (المُرسَلَ إليهم) فأخذهم الله أخذةً شديدةً زائدةً في الشدّة؛ ففي هذا بيانُ أنّ معصيةَ الرسلِ سببُ العذابِ الشديد؛ فأطع الرسلَ ولا تعصهم، فمعصيةُ الرسلِ سبيلُ العذاب، فاتّبعهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طاعةُ الرسلِ واتّباعُهم، والحذرُ من معصيتهم."},"action":{"text":"تأمّل عاقبةَ معصيةِ الرسل: فعصوا رسولَ ربّهم، أي عصت كلُّ أمّةٍ رسولَها المُرسَلَ إليها (فرعونُ عصى موسى، وقومُ لوطٍ عصوا لوطًا، وهكذا)؛ فأخذهم الله أخذةً رابيةً، أي شديدةً زائدةً في الشدّةِ والعظم، تربو على غيرها «فعصوا رسول ربهم فأخذهم أخذة رابية»؛ ففي هذا بيانُ أنّ سببَ عقوبةِ الأممِ معصيتُهم لرسلهم، وأنّ الله أخذهم أخذةً شديدةً بالغة؛ فمعصيةُ الرسلِ سببُ العذابِ الشديد؛ فأطع أنت الرسلَ (وخاتمهم محمدًا ﷺ) واتّبعهم، ولا تعصهم؛ ومن يعصِ الله ورسولَه فإنّ له نارَ جهنّم؛ فأخذناهم أخذَ عزيزٍ مقتدر؛ وكذلك أخذُ ربّك إذا أخذ القرى وهي ظالمة؛ فمعصيةُ الرسلِ سبيلُ العذابِ الشديد، وطاعتهم سبيلُ النجاة؛ فأطعهم، واتّبع سنّتهم، ولا تعصهم؛ فمن أطاع الرسلَ نجا، ومن عصاهم أُخِذ؛ فاجعل طاعةَ الرسلِ واتّباعَهم والحذرَ من معصيتهم دأبك."}}]},{"title":"نعمةُ النجاةِ وأهوالُ القيامةِ وعرضُ الأعمال","range":[11,18],"theme":"نعمةُ النجاةِ في السفينةِ لمّا طغى الماء «لنجعلها لكم تذكرة وتعيها أذن واعية»، ثم أهوالِ القيامة: النفخِ في الصورِ ودكِّ الأرضِ والجبال «فيومئذ وقعت الواقعة»، وانشقاقِ السماءِ وحملِ العرش «فوقهم يومئذ ثمانية»، وعرضِ الأعمال «يومئذ تعرضون لا تخفى منكم خافية»","verses":[{"n":11,"reflection":{"text":"«إنا لما طغى الماء حملناكم في الجارية»: إنا لمّا تجاوز الماءُ حدَّه (في الطوفان) حملنا آباءكم في السفينةِ الجارية؛ ففي هذا بيانُ نعمةِ النجاةِ من الطوفان؛ فاشكر الله على نعمةِ نجاةِ أصلك، فالنجاةُ من الله نعمة، فاشكرها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ النجاة، وتذكّرُ فضلِ الله على العباد."},"action":{"text":"تأمّل نعمةَ النجاة: إنا لمّا طغى الماءُ، أي تجاوز حدَّه وارتفع وعلا في الطوفانِ زمنَ نوح؛ حملناكم، أي حملنا آباءكم (الذين هم أصلكم، وهم نوحٌ ومن معه) في الجاريةِ، أي السفينةِ التي تجري على الماء «إنا لما طغى الماء حملناكم في الجارية»؛ ففي هذا بيانُ نعمةِ الله بنجاةِ نوحٍ ومن معه (أصولِ البشرِ الباقين) في السفينةِ من الطوفان، امتنانًا على الناس؛ فنجاةُ أصلكم نعمةٌ من الله؛ فاشكر أنت الله على نعمةِ النجاة، وتذكّر فضله على العباد؛ فأنجيناه وأصحابَ السفينة؛ وحملناه على ذاتِ ألواحٍ ودُسُر؛ وآيةٌ لهم أنا حملنا ذرّيّتهم في الفلكِ المشحون؛ فنجاةُ نوحٍ ومن معه نعمةٌ من الله على البشرِ جميعًا؛ فاشكرها، وتذكّر فضلَ الله، واعبده وحده؛ فمن شكر النعمةَ أفلح، ومن كفرها خسر؛ فاجعل شكرَ نعمةِ النجاةِ وتذكّرَ فضلِ الله على العبادِ دأبك."}},{"n":12,"reflection":{"text":"«لنجعلها لكم تذكرة وتعيها أذن واعية»: لنجعل تلك الحادثةَ (النجاةَ في السفينة) لكم عبرةً وعظة، وتحفظها وتعقلها أذنٌ حافظةٌ واعية؛ ففي هذا بيانُ حكمةِ العبرةِ والحثِّ على وعيها؛ فاجعل أذنك واعيةً للعبرِ والمواعظ، فوعيُ العبرةِ من التوفيق، فعِ ما تسمع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"وعيُ العبرِ والمواعظ، وحفظُها والعملُ بها."},"action":{"text":"تأمّل الحثَّ على الوعي: لنجعلها (تلك الحادثةَ، أو السفينةَ، أو النجاةَ) لكم تذكرةً، أي عبرةً وعظةً تُذكِّركم بقدرةِ الله ونعمته وعقوبةِ المكذّبين؛ وتعيها أذنٌ واعيةٌ، أي تحفظها وتعقلها وتنتفع بها أذنٌ من شأنها الحفظُ والفهمُ والعمل «لنجعلها لكم تذكرة وتعيها أذن واعية»؛ ففي هذا بيانُ حكمةِ جعلِ الحادثةِ عبرةً، والحثُّ على أن تعيها الأذنُ الواعيةُ الحافظة؛ فوعيُ العبرةِ من التوفيق؛ فاجعل أنت أذنك واعيةً للعبرِ والمواعظِ والقرآن، تحفظها وتعقلها وتعمل بها؛ إنّ في ذلك لذكرى لمن كان له قلبٌ أو ألقى السمعَ وهو شهيد؛ (ودعا النبيُّ ﷺ لعليٍّ أن يجعل الله أذنه واعية)؛ فوعيُ العبرةِ والموعظةِ من علاماتِ التوفيقِ والقلبِ الحيّ؛ فعِ ما تسمع من الحقِّ والعبر، واحفظه، واعمل به؛ فمن وعى العبرةَ وعمل بها اهتدى، ومن أعرض حُرِم؛ فاجعل وعيَ العبرِ والمواعظِ وحفظَها والعملَ بها دأبك."}},{"n":13,"reflection":{"text":"«فإذا نفخ في الصور نفخة واحدة»: فإذا نُفِخ في الصورِ نفخةٌ واحدةٌ (نفخةُ الصعقِ أو البعث)؛ ففي هذا بيانُ بدءِ أهوالِ القيامة؛ فاستعدّ ليومٍ يُنفَخ فيه في الصور، فالنفخُ في الصورِ بدءُ القيامة، فاعمل لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للنفخِ في الصور، والعملُ للقيامة."},"action":{"text":"تأمّل بدءَ الأهوال: فإذا نُفِخ في الصورِ (القرنِ الذي ينفخ فيه إسرافيلُ) نفخةٌ واحدةٌ، أي النفخةُ التي يكون بها قيامُ الساعةِ وبدءُ أهوالها (نفخةُ الصعقِ التي يموت بها الخلق، أو نفخةُ البعث) «فإذا نفخ في الصور نفخة واحدة»؛ ففي هذا بيانُ بدءِ أهوالِ القيامةِ بالنفخةِ الواحدةِ في الصور؛ فبها تبدأ الأهوالُ العظام؛ فاستعدّ أنت ليومٍ يُنفَخ فيه في الصورِ فتقوم القيامة؛ ونُفِخ في الصورِ فصعق من في السماواتِ ومن في الأرض؛ يومَ يُنفَخ في الصورِ فتأتون أفواجًا؛ فما هي إلا زجرةٌ واحدةٌ فإذا هم بالساهرة؛ فالنفخُ في الصورِ بدءُ القيامةِ وأهوالها؛ فاستعدّ له بالإيمانِ والعملِ الصالح؛ فمن استعدّ نجا، ومن غفل خسر؛ فاجعل الاستعدادَ للنفخِ في الصورِ والعملَ للقيامةِ دأبك."}},{"n":14,"reflection":{"text":"«وحملت الأرض والجبال فدكتا دكة واحدة»، ورُفِعت الأرضُ والجبالُ فدُكّتا (كُسِّرتا وسُحِقتا) دكّةً واحدة؛ ففي هذا بيانُ هولِ القيامةِ في زوالِ الأرضِ والجبال؛ فاستعدّ ليومٍ تُدَكّ فيه الأرضُ والجبال، فأهوالُ القيامةِ عظيمة، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ لهولِ زوالِ الأرضِ والجبال، والعملُ للقيامة."},"action":{"text":"تأمّل هولَ الدكّ: وحُمِلت الأرضُ والجبالُ، أي رُفِعت من أماكنها؛ فدُكّتا دكّةً واحدةً، أي كُسِّرتا وسُحِقتا وبُسِطتا بضربةٍ واحدةٍ فصارتا هباءً «وحملت الأرض والجبال فدكتا دكة واحدة»؛ ففي هذا بيانُ هولِ القيامةِ في رفعِ الأرضِ والجبالِ ودكّها دكّةً واحدةً حتى تصير مستويةً أو هباءً؛ فأهوالُ القيامةِ عظيمةٌ تزول لها الأرضُ والجبال؛ فاستعدّ أنت ليومٍ تُدَكّ فيه الأرضُ والجبال؛ كلّا إذا دُكّتِ الأرضُ دكًّا دكًّا؛ وحُمِلت الأرضُ والجبالُ فدُكّتا؛ ويومَ نُسيِّر الجبالَ وترى الأرضَ بارزة؛ فأهوالُ القيامةِ عظيمةٌ تُدَكّ لها الأرضُ والجبال؛ فاستعدّ لها بالإيمانِ والعملِ الصالح؛ فمن استعدّ نجا، ومن غفل خسر؛ فاجعل الاستعدادَ لهولِ زوالِ الأرضِ والجبالِ والعملَ للقيامةِ دأبك."}},{"n":15,"reflection":{"text":"«فيومئذ وقعت الواقعة»: فيومئذٍ وقعت القيامةُ (الواقعةُ التي لا بدّ منها)؛ ففي هذا تقريرُ وقوعِ القيامةِ عند تلك الأهوال؛ فأيقن بوقوعِ القيامةِ واستعدّ لها، فالقيامةُ واقعةٌ حتمًا، فاعمل لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بوقوعِ القيامة، والاستعدادُ لها."},"action":{"text":"تأمّل وقوعَ القيامة: فيومئذٍ، أي حين النفخِ ودكِّ الأرضِ والجبال، وقعت الواقعةُ، أي قامت القيامةُ التي لا بدّ من وقوعها، وحدثت أهوالها العظام «فيومئذ وقعت الواقعة»؛ ففي هذا تقريرُ وقوعِ القيامةِ عند تلك الأهوال (النفخِ والدكّ)؛ فالقيامةُ واقعةٌ حتمًا؛ فأيقن أنت بوقوعِ القيامةِ واستعدّ لها؛ إذا وقعت الواقعة * ليس لوقعتها كاذبة؛ فيومئذٍ وقعت الواقعة؛ وإنّ الدينَ لواقع؛ فالقيامةُ واقعةٌ حتمًا لا مردَّ لها؛ فأيقن بوقوعها، واستعدّ لها بالإيمانِ والعملِ الصالحِ والتقوى؛ فمن أيقن بها واستعدّ نجا، ومن أنكرها أو غفل خسر؛ فاجعل اليقينَ بوقوعِ القيامةِ والاستعدادَ لها دأبك."}},{"n":16,"reflection":{"text":"«وانشقت السماء فهي يومئذ واهية»، وانشقّت السماءُ (تصدّعت) فهي يومئذٍ ضعيفةٌ مسترخيةٌ بعد قوّتها؛ ففي هذا بيانُ هولِ انشقاقِ السماء؛ فاستعدّ ليومٍ تنشقّ فيه السماءُ القويّة، فإذا وهت السماءُ فما بالك بغيرها، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ لهولِ انشقاقِ السماء، والعملُ للقيامة."},"action":{"text":"تأمّل انشقاقَ السماء: وانشقّت السماءُ، أي تصدّعت وتفطّرت عند قيامِ الساعة؛ فهي يومئذٍ واهيةٌ، أي ضعيفةٌ مسترخيةٌ متمزّقةٌ بعد أن كانت محكمةً قويّةً شديدة «وانشقت السماء فهي يومئذ واهية»؛ ففي هذا بيانُ هولِ انشقاقِ السماءِ القويّةِ المحكمةِ وصيرورتها واهيةً ضعيفةً يومَ القيامة؛ فإذا وهت السماءُ القويّةُ فما بالُ غيرها؟ فاستعدّ أنت ليومٍ تنشقّ فيه السماء؛ إذا السماءُ انشقّت وأذنت لربّها وحُقّت؛ يومَ تشقّق السماءُ بالغمام؛ فإذا انشقّتِ السماءُ فكانت وردةً كالدهان؛ فانشقاقُ السماءِ القويّةِ من أهوالِ القيامةِ العظام؛ فاستعدّ لها بالإيمانِ والعملِ الصالح؛ فمن استعدّ نجا، ومن غفل خسر؛ فاجعل الاستعدادَ لهولِ انشقاقِ السماءِ والعملَ للقيامةِ دأبك."}},{"n":17,"reflection":{"text":"«والملك على أرجائها ويحمل عرش ربك فوقهم يومئذ ثمانية»، والملائكةُ على جوانبِ السماء، ويحمل عرشَ ربّك فوقهم يومئذٍ ثمانيةٌ (من الملائكةِ، أو من صفوفهم)؛ ففي هذا بيانُ عظمةِ الله وعرشِه وملائكتِه يومَ القيامة؛ فعظّم ربَّك ذا العرشِ العظيم، فعظمةُ الله تُبهِر العقول، فعظّمه واخضع له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الله ذي العرشِ العظيم، والخضوعُ له."},"action":{"text":"تأمّل عظمةَ العرشِ والملائكة: والملكُ (جنسُ الملائكة) على أرجائها، أي على جوانبِ السماءِ وأطرافها ونواحيها؛ ويحمل عرشَ ربّك فوقهم يومئذٍ ثمانيةٌ، أي ثمانيةٌ من الملائكةِ العظام (أو ثمانيةُ صفوف) يحملون العرشَ يومَ القيامة «والملك على أرجائها ويحمل عرش ربك فوقهم يومئذ ثمانية»؛ ففي هذا بيانُ عظمةِ الله وعرشِه وملائكتِه يومَ القيامة، حيث تكون الملائكةُ على جوانبِ السماء، ويحمل العرشَ ثمانيةٌ من عظامِ الملائكة؛ فعظمةُ العرشِ تدلّ على عظمةِ الربّ؛ فعظّم أنت ربَّك ذا العرشِ العظيم، واخضع له؛ الذين يحملون العرشَ ومن حوله يسبّحون بحمدِ ربّهم؛ وترى الملائكةَ حافّين من حولِ العرش؛ ربُّ العرشِ العظيم؛ فعظمةُ العرشِ وحملتِه تدلّ على عظمةِ الله الجليل؛ فعظّمه، واخضع له، وأخلِص له العبادة؛ فمن عظّم الله وخضع له أفلح، ومن استكبر خسر؛ فاجعل تعظيمَ الله ذي العرشِ العظيمِ والخضوعَ له دأبك."}},{"n":18,"reflection":{"text":"«يومئذ تعرضون لا تخفى منكم خافية»: يومئذٍ تُعرَضون على الله للحساب، لا تخفى منكم خافيةٌ (سريرةٌ ولا عمل)؛ ففي هذا بيانُ العرضِ على الله وانكشافِ الأسرار؛ فاستعدّ ليومٍ تنكشف فيه أسرارك على الله، فأعمالك ستُعرَض وأسرارك ستُكشَف، فأصلِح سرّك وعلنك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للعرضِ على الله، وإصلاحُ السرِّ والعلن."},"action":{"text":"تأمّل العرضَ على الله: يومئذٍ تُعرَضون، أي تُعرَضون على الله للحسابِ والجزاء؛ لا تخفى منكم خافيةٌ، أي لا يخفى على الله شيءٌ من أعمالكم وأسراركم وسرائركم، بل تنكشف كلُّها «يومئذ تعرضون لا تخفى منكم خافية»؛ ففي هذا بيانُ أنّ الناسَ يُعرَضون على الله يومَ القيامةِ للحساب، وأنّ أسرارهم وأعمالهم كلَّها تنكشف فلا يخفى منها شيء؛ فأعمالك وأسرارك ستُعرَض وتُكشَف؛ فاستعدّ أنت ليومٍ تنكشف فيه أسرارك وأعمالك على الله؛ يومَ تُبلى السرائر؛ وعُرِضوا على ربّك صفًّا لقد جئتمونا كما خلقناكم أوّلَ مرّة؛ يومئذٍ تُعرَضون لا تخفى منكم خافية؛ فأعمالك وأسرارك ستُعرَض على الله وتُكشَف يومَ القيامة؛ فأصلِح سرّك وعلنك، وطهّر قلبك ونيّتك، واستعدّ للعرض؛ فمن أصلح سرّه وعلنه نجا، ومن أفسدهما خُزِي؛ فاجعل الاستعدادَ للعرضِ على الله وإصلاحَ السرِّ والعلنِ دأبك."}}]},{"title":"أخذُ الكتبِ بالأيمانِ والشمائلِ وجزاءُ الفريقين","range":[19,37],"theme":"مشهدُ أخذِ الكتب: السعيدُ يأخذ كتابه بيمينه فرحًا «هاؤم اقرءوا كتابيه إني ظننت أني ملاق حسابيه» فينعم «كلوا واشربوا هنيئا بما أسلفتم في الأيام الخالية»، والشقيُّ يأخذه بشماله متحسّرًا «يا ليتني لم أوت كتابيه... ما أغنى عني ماليه هلك عني سلطانيه» فيُعذَّب «خذوه فغلوه ثم الجحيم صلوه»، وأنّ سببَ عذابه «كان لا يؤمن بالله العظيم ولا يحض على طعام المسكين»","verses":[{"n":19,"reflection":{"text":"«فأما من أوتي كتابه بيمينه فيقول هاؤم اقرءوا كتابيه»: فأمّا من أُعطِيَ كتابَ عمله بيمينه (من السعداء) فيقول فرحًا: هاؤم (خذوا) اقرؤوا كتابيه؛ ففي هذا بيانُ فرحِ السعيدِ بكتابه؛ فاعمل صالحًا لتأخذ كتابك بيمينك فرحًا، فأخذُ الكتابِ باليمينِ فوز، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لأخذِ الكتابِ باليمين، والفرحُ بالعملِ الصالح."},"action":{"text":"تأمّل فرحَ السعيد: فأمّا من أُوتِيَ كتابَه (كتابَ أعماله) بيمينه، وهم السعداءُ أهلُ الجنّة؛ فيقول من فرحه وسروره لمن حوله: هاؤمُ (خذوا) اقرؤوا كتابيه، أي كتابي، مبتهجًا بما فيه من الحسناتِ والنجاة «فأما من أوتي كتابه بيمينه فيقول هاؤم اقرءوا كتابيه»؛ ففي هذا بيانُ حالِ السعيدِ الذي يأخذ كتابَه بيمينه، فيفرح ويبتهج ويدعو الناسَ لقراءته؛ فأخذُ الكتابِ باليمينِ علامةُ الفوز؛ فاعمل أنت صالحًا لتأخذ كتابك بيمينك فرحًا مسرورًا؛ فأمّا من أُوتِيَ كتابه بيمينه فسوف يُحاسَب حسابًا يسيرًا وينقلب إلى أهله مسرورًا؛ ويؤتَ كتابه بيمينه؛ فأخذُ الكتابِ باليمينِ فوزٌ وبشرى؛ فاعمل بالإيمانِ والطاعةِ لتنال ذلك، وافرح بالعملِ الصالح؛ فمن عمل صالحًا أخذ كتابه بيمينه وفرح، ومن أساء أخذه بشماله وحزن؛ فاجعل العملَ لأخذِ الكتابِ باليمينِ والفرحَ بالعملِ الصالحِ دأبك."}},{"n":20,"reflection":{"text":"«إني ظننت أني ملاق حسابيه»: إني أيقنتُ في الدنيا أني ملاقٍ حسابي فاستعددتُ له؛ ففي هذا بيانُ أنّ اليقينَ بالحسابِ ثمرته الاستعدادُ والفوز؛ فأيقن بلقاءِ الحسابِ واستعدّ له لتفوز، فاليقينُ بالحسابِ يورث الاستعداد، فأيقن واستعدّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بلقاءِ الحساب، والاستعدادُ له بالعمل."},"action":{"text":"تأمّل ثمرةَ اليقين بالحساب: إني ظننتُ، أي أيقنتُ (والظنُّ هنا بمعنى اليقين)، وأني ملاقٍ حسابيه، أي أني ملاقٍ حسابي يومَ القيامة، فآمنتُ بذلك في الدنيا واستعددتُ له بالعملِ الصالح «إني ظننت أني ملاق حسابيه»؛ ففي هذا بيانُ سببِ فوزِ السعيد: أنه أيقن في الدنيا بلقاءِ الحسابِ فاستعدّ له بالإيمانِ والعمل؛ فاليقينُ بالحسابِ ثمرته الاستعدادُ والفوز؛ فأيقن أنت بلقاءِ الحسابِ واستعدّ له بالعملِ الصالح؛ الذين يظنّون أنهم ملاقو ربّهم؛ إني ظننتُ أني ملاقٍ حسابيه؛ ألا يظنّ أولئك أنهم مبعوثون ليومٍ عظيم؛ فاليقينُ بلقاءِ الحسابِ يورث الاستعدادَ والتقوى والفوز؛ فأيقن به، واستعدّ له، واعمل صالحًا؛ فمن أيقن بالحسابِ واستعدّ فاز، ومن غفل عنه خسر؛ فاجعل اليقينَ بلقاءِ الحسابِ والاستعدادَ له بالعملِ دأبك."}},{"n":21,"reflection":{"text":"«فهو في عيشة راضية»: فهو في عيشةٍ مرضيّةٍ يرضاها (في الجنّة)؛ ففي هذا بيانُ جزاءِ السعيد؛ فاعمل لتنال العيشةَ الراضيةَ في الجنّة، فالعيشةُ الراضيةُ جزاءُ العملِ الصالح، فاعمل لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ العيشةِ الراضيةِ في الجنّة."},"action":{"text":"تأمّل جزاءَ السعيد: فهو في عيشةٍ راضيةٍ، أي في حياةٍ مرضيّةٍ طيّبةٍ يرضاها ويطمئنّ إليها، لا نكدَ فيها ولا كدر، في الجنّة «فهو في عيشة راضية»؛ ففي هذا بيانُ جزاءِ السعيدِ الذي أخذ كتابه بيمينه: عيشةٌ راضيةٌ في الجنّة؛ فجزاؤه العيشةُ الطيّبةُ المرضيّة؛ فاعمل أنت لتنال العيشةَ الراضيةَ في الجنّة؛ فأمّا من ثقلت موازينه فهو في عيشةٍ راضية؛ لهم دارُ السلامِ عند ربّهم؛ فمن عمل صالحًا من ذكرٍ أو أنثى وهو مؤمنٌ فلنُحيِينّه حياةً طيّبة؛ فالعيشةُ الراضيةُ جزاءُ العملِ الصالحِ والإيمان؛ فاعمل لها بالإيمانِ والطاعة؛ فمن عمل صالحًا نالها، ومن أساء حُرِمها؛ فاجعل العملَ لنيلِ العيشةِ الراضيةِ في الجنّةِ دأبك."}},{"n":22,"reflection":{"text":"«في جنة عالية»: في جنّةٍ عاليةِ المكانِ والمنزلةِ والدرجات؛ ففي هذا بيانُ علوِّ منزلةِ السعيد؛ فاعمل لتنال الجنّةَ العاليةَ المنزلة، فالجنّةُ العاليةُ للمحسنين، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ الجنّةِ العاليةِ المنزلة."},"action":{"text":"تأمّل علوَّ الجنّة: في جنّةٍ عاليةٍ، أي رفيعةِ المكانِ (فوق) وعاليةِ المنزلةِ والدرجاتِ والقدر «في جنة عالية»؛ ففي هذا بيانُ علوِّ منزلةِ السعيدِ في الجنّةِ العاليةِ المكانِ والقدر؛ فجنّته عاليةٌ رفيعة؛ فاعمل أنت لتنال الجنّةَ العاليةَ المنزلة؛ وجوهٌ يومئذٍ ناعمة لسعيها راضية في جنّةٍ عالية؛ في جنّاتٍ ونهر في مقعدِ صدقٍ عند مليكٍ مقتدر؛ ورفعنا بعضهم فوق بعضٍ درجات؛ فالجنّةُ العاليةُ المنزلةِ للمحسنين السابقين؛ فاعمل لها بالإحسانِ والسبقِ إلى الخيرات؛ فمن أحسن وسابق نال الدرجاتِ العلى، ومن قصّر نقص؛ فاجعل العملَ لنيلِ الجنّةِ العاليةِ المنزلةِ دأبك."}},{"n":23,"reflection":{"text":"«قطوفها دانية»: ثمارها قريبةٌ سهلةُ التناولِ لمن أرادها؛ ففي هذا بيانُ سهولةِ نعيمِ الجنّة؛ فاعمل لتنال نعيمًا سهلَ التناول، فنعيمُ الجنّةِ ميسورٌ لأهلها، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ الميسورِ التناول."},"action":{"text":"تأمّل سهولةَ ثمارِ الجنّة: قطوفها دانيةٌ، أي ثمارها (ما يُقطَف منها) قريبةٌ دانيةٌ سهلةُ التناولِ، ينالها القائمُ والقاعدُ والمضطجعُ بلا مشقّةٍ ولا تعب «قطوفها دانية»؛ ففي هذا بيانُ سهولةِ نعيمِ الجنّةِ وتيسّرِ ثمارها لأهلها؛ فثمارها قريبةٌ ميسورة؛ فاعمل أنت لتنال نعيمًا سهلَ التناولِ في الجنّة؛ ودانيةً عليهم ظلالها وذُلِّلت قطوفها تذليلًا؛ وجنى الجنّتين دان؛ متّكئين فيها يدعون فيها بفاكهةٍ كثيرة؛ فنعيمُ الجنّةِ ميسورٌ لأهلها بلا مشقّة؛ فاعمل له بالإيمانِ والطاعة؛ فمن عمل صالحًا نال هذا النعيمَ الميسور، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ الميسورِ التناولِ دأبك."}},{"n":24,"reflection":{"text":"«كلوا واشربوا هنيئا بما أسلفتم في الأيام الخالية»: يُقال لهم: كلوا واشربوا هنيئًا (بلا تنغيص) جزاءً بما قدّمتم من الأعمالِ الصالحةِ في أيّامِ الدنيا الماضية؛ ففي هذا بيانُ أنّ نعيمَ الجنّةِ ثمرةُ ما قُدِّم في الدنيا؛ فقدّم عملًا صالحًا في أيّامك لتأكل هنيئًا في الجنّة، فما تقدّمه اليومَ تجده غدًا، فاعمل واقدّم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقديمُ العملِ الصالحِ في الدنيا لنعيمِ الآخرة."},"action":{"text":"تأمّل أنّ النعيمَ ثمرةُ ما قُدِّم: كلوا واشربوا، يُقال للسعداءِ تكريمًا، هنيئًا، أي أكلًا وشربًا هنيئًا لا تنغيصَ فيه ولا أذى؛ بما أسلفتم، أي جزاءً بما قدّمتم من الأعمالِ الصالحةِ، في الأيّامِ الخاليةِ، أي الماضيةِ في الدنيا «كلوا واشربوا هنيئا بما أسلفتم في الأيام الخالية»؛ ففي هذا بيانُ أنّ نعيمَ الجنّةِ (الأكلَ والشربَ الهنيء) ثمرةُ ما قدّمه العبدُ من العملِ الصالحِ في أيّامِ الدنيا؛ فما قدّمته اليومَ تجده غدًا هنيئًا؛ فقدّم أنت عملًا صالحًا في أيّامك المعدودةِ لتأكل وتشرب هنيئًا في الجنّة؛ ذلك بما قدّمت أيديكم؛ ولتنظر نفسٌ ما قدّمت لغد؛ وما تقدّموا لأنفسكم من خيرٍ تجدوه عند الله؛ فنعيمُ الجنّةِ ثمرةُ العملِ الصالحِ المُقدَّمِ في الدنيا؛ فاغتنم أيّامك، وقدّم العملَ الصالح، لتجده هنيئًا في الآخرة؛ فمن قدّم صالحًا نال النعيمَ الهنيء، ومن فرّط ندم؛ فاجعل تقديمَ العملِ الصالحِ في الدنيا لنعيمِ الآخرةِ دأبك."}},{"n":25,"reflection":{"text":"«وأما من أوتي كتابه بشماله فيقول يا ليتني لم أوت كتابيه»، وأمّا من أُعطِيَ كتابَه بشماله (من الأشقياء) فيقول متحسّرًا: يا ليتني لم أُعطَ كتابي؛ ففي هذا بيانُ حسرةِ الشقيِّ بكتابه؛ فاحذر أن تأخذ كتابك بشمالك بالإيمانِ والعمل، فأخذُ الكتابِ بالشمالِ حسرة، فاعمل لتنجو منها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أخذِ الكتابِ بالشمال، والعملُ للنجاة."},"action":{"text":"تأمّل حسرةَ الشقيّ: وأمّا من أُوتِيَ كتابَه بشماله، وهم الأشقياءُ أهلُ النار؛ فيقول من شدّةِ الحسرةِ والندمِ لمّا يرى سيّئاته: يا ليتني لم أُوتَ كتابيه، أي يا ليتني لم أُعطَ كتابي ولم أعلم ما فيه «وأما من أوتي كتابه بشماله فيقول يا ليتني لم أوت كتابيه»؛ ففي هذا بيانُ حالِ الشقيِّ الذي يأخذ كتابه بشماله، فيتحسّر ويتمنّى أنه لم يُعطَه لِما فيه من السيّئات؛ فأخذُ الكتابِ بالشمالِ حسرةٌ وندم؛ فاحذر أنت أن تأخذ كتابك بشمالك، بالإيمانِ والعملِ الصالح؛ وأمّا من أُوتِيَ كتابه وراءَ ظهره فسوف يدعو ثبورًا؛ فيقول يا ليتني قدّمتُ لحياتي؛ يا حسرتى على ما فرّطت؛ فأخذُ الكتابِ بالشمالِ حسرةٌ لا تنفع؛ فاعمل صالحًا في الدنيا لتنجوَ من هذه الحسرة؛ فمن عمل صالحًا أخذ كتابه بيمينه، ومن أساء أخذه بشماله وتحسّر؛ فاجعل الحذرَ من أخذِ الكتابِ بالشمالِ والعملَ للنجاةِ دأبك."}},{"n":26,"reflection":{"text":"«ولم أدر ما حسابيه»، وليتني لم أعلم ما حسابي (من شدّةِ هوله)؛ ففي هذا زيادةُ حسرةِ الشقيّ؛ فاستعدّ للحسابِ قبل أن تتمنّى ألّا تعلمه، فحسابُ الشقيِّ حسرة، فاعمل لتنجو منه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للحسابِ بالعمل، والحذرُ من حسرته."},"action":{"text":"تأمّل زيادةَ حسرته: ولم أدرِ ما حسابيه، أي ويا ليتني لم أعلم ما حسابي، فقد تمنّى ألّا يكون علم بحسابه من شدّةِ هوله وسوءِ عاقبته؛ زيادةً في الحسرةِ على ما تقدّم «ولم أدر ما حسابيه»؛ ففي هذا بيانُ زيادةِ حسرةِ الشقيِّ حتى تمنّى ألّا يعلم حسابه لهوله؛ فحسابه حسرةٌ عليه؛ فاستعدّ أنت للحسابِ في الدنيا بالعملِ الصالح، قبل أن تتمنّى ألّا تعلمه؛ فأمّا من أُوتِيَ كتابه بشماله... ولم أدرِ ما حسابيه؛ وحاسبوا أنفسكم قبل أن تُحاسَبوا؛ فمن نُوقِش الحسابَ عُذِّب؛ فحسابُ الشقيِّ حسرةٌ وعذاب؛ فاستعدّ له بالعملِ الصالحِ ومحاسبةِ النفس؛ فمن حاسب نفسه واستعدّ نجا، ومن غفل تحسّر؛ فاجعل الاستعدادَ للحسابِ بالعملِ والحذرَ من حسرته دأبك."}},{"n":27,"reflection":{"text":"«يا ليتها كانت القاضية»: يا ليت الموتةَ (الأولى) كانت القاضيةَ (المُنهيةَ لأمري فلم أُبعَث)؛ ففي هذا بيانُ تمنّي الشقيِّ الموتَ الدائم؛ فاعمل لئلا تتمنّى الموتَ يومَ القيامة، فتمنّي الموتِ يومئذٍ حسرة، فاعمل لتنجو.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنجاةِ من حسرةِ تمنّي الموت."},"action":{"text":"تأمّل تمنّيه الموتَ الدائم: يا ليتها، أي الموتةَ الأولى في الدنيا، كانت القاضيةَ، أي المُنهيةَ لأمري القاطعةَ لحياتي، فلم أُبعَث ولم أرَ هذا العذاب؛ فتمنّى الموتَ الدائمَ الذي لا حياةَ بعده «يا ليتها كانت القاضية»؛ ففي هذا بيانُ تمنّي الشقيِّ الموتَ الذي لا بعثَ بعده، من شدّةِ العذابِ والحسرة؛ فيتمنّى الفناءَ ولا يجده؛ فاعمل أنت لئلا تتمنّى الموتَ يومَ القيامة؛ ويقول الكافرُ يا ليتني كنتُ ترابًا؛ يا ليتني متُّ قبل هذا؛ ونادوا يا مالكُ ليقضِ علينا ربّك قال إنكم ماكثون؛ فتمنّي الموتِ يومَ القيامةِ حسرةٌ لأهلِ النار؛ فاعمل صالحًا في الدنيا لتنجوَ من هذه الحسرة؛ فمن عمل صالحًا نجا، ومن أساء تمنّى الموتَ فلم يجده؛ فاجعل العملَ للنجاةِ من حسرةِ تمنّي الموتِ دأبك."}},{"n":28,"reflection":{"text":"«ما أغنى عني ماليه»: ما نفعني مالي ولم يدفع عنّي العذاب؛ ففي هذا بيانُ أنّ المالَ لا يُغني يومَ القيامة؛ فلا تعتمد على مالك واعمل صالحًا، فالمالُ لا يُغني من الله، فاعمل لما ينفع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاعتمادِ على المال، والعملُ لما ينفعُ يومَ القيامة."},"action":{"text":"تأمّل أنّ المالَ لا يُغني: ما أغنى عنّي ماليه، أي ما نفعني مالي الذي جمعته وبخلت به، ولم يدفع عنّي العذابَ ولا نفعني شيئًا «ما أغنى عني ماليه»؛ ففي هذا بيانُ ندمِ الشقيِّ على اعتماده على ماله، وأنّ المالَ لا يُغني عن صاحبه يومَ القيامة؛ فماله الذي اتّكل عليه لم ينفعه؛ فلا تعتمد أنت على مالك، واعمل صالحًا؛ لن تُغنيَ عنهم أموالهم ولا أولادهم من الله شيئًا؛ يومَ لا ينفع مالٌ ولا بنون؛ وما أموالكم ولا أولادكم بالتي تقرّبكم عندنا زلفى؛ فالمالُ لا يُغني من الله شيئًا يومَ القيامة؛ فلا تعتمد عليه، واعمل لما ينفعك من الإيمانِ والعملِ الصالحِ والإنفاق؛ فمن اعتمد على عمله الصالحِ نجا، ومن اتّكل على ماله ندم؛ فاجعل عدمَ الاعتمادِ على المالِ والعملَ لما ينفعُ يومَ القيامةِ دأبك."}},{"n":29,"reflection":{"text":"«هلك عني سلطانيه»: ذهب عنّي سلطاني وحجّتي وقوّتي؛ ففي هذا بيانُ زوالِ السلطانِ والقوّةِ يومَ القيامة؛ فلا تغترّ بسلطانٍ ولا قوّةٍ واعمل صالحًا، فالسلطانُ يزول والعملُ يبقى، فاعمل للباقي.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالسلطانِ والقوّة، والعملُ للباقي."},"action":{"text":"تأمّل زوالَ السلطان: هلك عنّي سلطانيه، أي ذهب عنّي سلطاني وقوّتي وحجّتي وملكي الذي كنتُ أعتزّ به في الدنيا، فلم يبقَ لي شيء «هلك عني سلطانيه»؛ ففي هذا بيانُ ندمِ الشقيِّ على اغتراره بسلطانه وقوّته، وأنها زالت عنه يومَ القيامةِ فلم تنفعه؛ فسلطانه وقوّته زالا؛ فلا تغترّ أنت بسلطانٍ ولا قوّةٍ ولا جاه، واعمل صالحًا؛ لمنِ الملكُ اليومَ لله الواحدِ القهّار؛ وضلّ عنهم ما كانوا يفترون؛ ولقد جئتمونا فرادى كما خلقناكم أوّلَ مرّةٍ وتركتم ما خوّلناكم وراءَ ظهوركم؛ فالسلطانُ والقوّةُ يزولان يومَ القيامةِ فلا يبقى إلا العمل؛ فلا تغترّ بهما، واعمل للباقي (الإيمانِ والعملِ الصالح)؛ فمن عمل للباقي نجا، ومن اغترّ بالفاني ندم؛ فاجعل عدمَ الاغترارِ بالسلطانِ والقوّةِ والعملَ للباقي دأبك."}},{"n":30,"reflection":{"text":"«خذوه فغلوه»: يُقال للملائكة: خذوا هذا الشقيَّ فاجمعوا يديه إلى عنقه بالأغلال؛ ففي هذا بيانُ إذلالِ الشقيِّ وعقوبته؛ فاحذر عقوبةً هذا هولها بالإيمانِ والعمل، فعقوبةُ الشقيِّ مذلّة، فاعمل لتنجو منها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عقوبةِ الشقيّ، والعملُ للنجاةِ منها."},"action":{"text":"تأمّل عقوبةَ الشقيّ: خذوه، يُقال للملائكةِ الغلاظِ الشداد: خذوا هذا الشقيّ؛ فغلّوه، أي اجمعوا يديه إلى عنقه بالأغلالِ إذلالًا وتعذيبًا «خذوه فغلوه»؛ ففي هذا بيانُ عقوبةِ الشقيِّ وإذلاله بالأخذِ والغلّ؛ فيُؤخَذ ويُغَلّ ويُذَلّ؛ فاحذر أنت عقوبةً هذا هولها، بالإيمانِ والعملِ الصالح؛ إذِ الأغلالُ في أعناقهم والسلاسلُ يُسحَبون؛ خذوه فاعتلوه إلى سواءِ الجحيم؛ إنا أعتدنا للكافرين سلاسلَ وأغلالًا وسعيرًا؛ فعقوبةُ الشقيِّ الأخذُ والغلُّ والإذلال؛ فاعمل للنجاةِ منها بالإيمانِ والطاعةِ والتقوى؛ فمن عمل للنجاةِ نجا، ومن غفل وقع فيها؛ فاجعل الحذرَ من عقوبةِ الشقيِّ والعملَ للنجاةِ منها دأبك."}},{"n":31,"reflection":{"text":"«ثم الجحيم صلوه»: ثم أدخلوه الجحيمَ يُقاسي حرَّها؛ ففي هذا بيانُ عذابِ الشقيِّ في الجحيم؛ فاحذر نارَ الجحيمِ بالإيمانِ والعمل، فالجحيمُ مصيرُ الشقيّ، فاعمل لتنجو منها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من نارِ الجحيم، والعملُ للنجاةِ منها."},"action":{"text":"تأمّل عذابَ الجحيم: ثم الجحيمَ صلّوه، أي ثم أدخلوه الجحيمَ (النارَ العظيمة) وأصلوه إيّاها لِيُقاسي حرَّها وعذابها «ثم الجحيم صلوه»؛ ففي هذا بيانُ عذابِ الشقيِّ بإدخاله الجحيمَ بعد أخذه وغلّه؛ فيُصلى النارَ ويُعذَّب بها؛ فاحذر أنت نارَ الجحيمِ بالإيمانِ والعملِ الصالح؛ ثم الجحيمَ صلّوه؛ اصلوها فاصبروا أو لا تصبروا؛ ثم إنهم لصالو الجحيم؛ فالجحيمُ مصيرُ الشقيِّ الكافر؛ فاعمل للنجاةِ منها بالإيمانِ والطاعةِ والتقوى؛ فمن عمل للنجاةِ نجا، ومن أساء صار إليها؛ فاجعل الحذرَ من نارِ الجحيمِ والعملَ للنجاةِ منها دأبك."}},{"n":32,"reflection":{"text":"«ثم في سلسلة ذرعها سبعون ذراعا فاسلكوه»: ثم في سلسلةٍ طولها سبعون ذراعًا فأدخلوه فيها؛ ففي هذا بيانُ تمامِ عذابِ الشقيّ؛ فاحذر عذابَ السلاسلِ بالإيمانِ والعمل، فعذابُ الشقيِّ شديد، فاعمل لتنجو منه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ الشقيِّ الشديد، والعملُ للنجاة."},"action":{"text":"تأمّل تمامَ عذابه: ثم في سلسلةٍ ذرعها (طولها) سبعون ذراعًا، أي سلسلةٍ طويلةٍ عظيمة، فاسلكوه، أي أدخلوه فيها، تُدخَل من دبره وتخرج من فمه، أو يُلَفّ بها «ثم في سلسلة ذرعها سبعون ذراعا فاسلكوه»؛ ففي هذا بيانُ تمامِ عذابِ الشقيّ: أن يُدخَل في سلسلةٍ عظيمةٍ طولها سبعون ذراعًا؛ فيُعذَّب بالسلاسلِ زيادةً على النار؛ فاحذر أنت عذابَ السلاسلِ والأغلالِ بالإيمانِ والعملِ الصالح؛ إنا أعتدنا للكافرين سلاسلَ وأغلالًا وسعيرًا؛ في سلسلةٍ ذرعها سبعون ذراعًا فاسلكوه؛ خذوه فغلّوه ثم الجحيمَ صلّوه؛ فعذابُ الشقيِّ شديدٌ متنوّعٌ (أخذٌ وغلٌّ ونارٌ وسلاسل)؛ فاعمل للنجاةِ منه بالإيمانِ والطاعة؛ فمن عمل للنجاةِ نجا، ومن أساء عُذِّب؛ فاجعل الحذرَ من عذابِ الشقيِّ الشديدِ والعملَ للنجاةِ دأبك."}},{"n":33,"reflection":{"text":"«إنه كان لا يؤمن بالله العظيم»: إنّ سببَ عذابه أنه كان لا يؤمن بالله العظيم؛ ففي هذا بيانُ أنّ الكفرَ سببُ العذاب؛ فآمن بالله العظيمِ إيمانًا صادقًا لتنجو، فالإيمانُ بالله سبيلُ النجاة، فآمن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بالله العظيمِ إيمانًا صادقًا، والنجاةُ به."},"action":{"text":"تأمّل السببَ الأولَ للعذاب: إنه كان لا يؤمن بالله العظيمِ، أي إنّ سببَ عذابه الأولَ أنه كان في الدنيا لا يؤمن بالله العظيمِ ولا يوحّده، بل يكفر به ويشرك «إنه كان لا يؤمن بالله العظيم»؛ ففي هذا بيانُ أنّ السببَ الأولَ لعذابِ الشقيِّ عدمُ إيمانه بالله العظيم (الكفرُ والشرك)؛ فالكفرُ سببُ العذاب؛ فآمن أنت بالله العظيمِ إيمانًا صادقًا (توحيدًا وتصديقًا وطاعة) لتنجو؛ إنه كان لا يؤمن بالله العظيم؛ إنّ الشركَ لظلمٌ عظيم؛ والذين كفروا وكذّبوا بآياتنا أولئك أصحابُ النار؛ فالكفرُ بالله سببُ العذاب، والإيمانُ به سبيلُ النجاة؛ فآمن بالله العظيمِ وحّده وعظّمه وأطعه؛ فمن آمن بالله نجا، ومن كفر به عُذِّب؛ فاجعل الإيمانَ بالله العظيمِ إيمانًا صادقًا والنجاةَ به دأبك."}},{"n":34,"reflection":{"text":"«ولا يحض على طعام المسكين»، ولا يحثّ نفسه ولا غيره على إطعامِ المسكين (بخلًا وقسوة)؛ ففي هذا بيانُ أنّ منعَ الخيرِ عن المساكين سببُ العذاب؛ فأطعم المسكينَ وحُثّ عليه، فمنعُ الخيرِ سبيلُ العذاب، فابذل وحُثّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إطعامُ المسكينِ والحثُّ عليه، والحذرُ من منعِ الخير."},"action":{"text":"تأمّل السببَ الثانيَ للعذاب: ولا يحضّ على طعامِ المسكينِ، أي ولا يحثّ نفسه ولا غيره على إطعامِ الفقيرِ المحتاج، بخلًا وقسوةً وعدمَ رحمة؛ فجمع بين الكفرِ بالخالقِ وقطعِ الإحسانِ إلى الخلق «ولا يحض على طعام المسكين»؛ ففي هذا بيانُ السببِ الثاني لعذابِ الشقيّ: أنه لا يحضّ على إطعامِ المساكين، فجمع بين سوءِ العلاقةِ مع الله (الكفر) وسوءِ العلاقةِ مع الخلق (منعِ الإحسان)؛ فمنعُ الخيرِ عن المساكين سببُ العذاب؛ فأطعم أنت المسكين، وحُثّ عليه، وارحم الفقراء؛ أرأيت الذي يكذّب بالدين فذلك الذي يدعّ اليتيم ولا يحضّ على طعامِ المسكين؛ وتحاضّون على طعامِ المسكين؛ فمنعُ الخيرِ عن المساكينِ وعدمُ الحضِّ عليه من صفاتِ الأشقياء؛ فأطعم المسكين، وحُثّ الناسَ عليه، وارحم الضعفاء؛ فمن أطعم وحضّ نجا، ومن بخل ومنع عُذِّب؛ فاجعل إطعامَ المسكينِ والحثَّ عليه والحذرَ من منعِ الخيرِ دأبك."}},{"n":35,"reflection":{"text":"«فليس له اليوم هاهنا حميم»: فليس له اليومَ (في النار) قريبٌ ولا صديقٌ يحميه؛ ففي هذا بيانُ انقطاعِ النصرةِ عن الشقيّ؛ فاطلب وليًّا ينفعك يومَ القيامةِ (وهو الله) بالإيمانِ والطاعة، فلا نصيرَ يومئذٍ إلا العملُ الصالح، فاعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ ولايةِ الله بالإيمانِ والطاعة، والعملُ لما ينصر."},"action":{"text":"تأمّل انقطاعَ النصرة: فليس له اليومَ (يومَ القيامةِ في النار) هاهنا (في هذا الموقف) حميمٌ، أي قريبٌ مشفقٌ أو صديقٌ حميمٌ يحميه أو ينفعه أو يدفع عنه العذاب «فليس له اليوم هاهنا حميم»؛ ففي هذا بيانُ انقطاعِ النصرةِ والشفاعةِ عن الشقيِّ يومَ القيامة، فلا قريبَ ولا صديقَ ينفعه؛ فلا نصيرَ له؛ فاطلب أنت وليًّا وحميمًا ينفعك يومَ القيامةِ (وهو الله بطاعته، والعملُ الصالح)؛ فما لنا من شافعين ولا صديقٍ حميم؛ ولا يسأل حميمٌ حميمًا؛ الأخلّاءُ يومئذٍ بعضهم لبعضٍ عدوٌّ إلا المتّقين؛ فلا ينفع يومَ القيامةِ قريبٌ ولا صديقٌ إلا العملُ الصالحُ وولايةُ الله؛ فاطلب ولايةَ الله بالإيمانِ والطاعة، واعمل لما ينصرك؛ فمن والى الله وعمل صالحًا نُصِر، ومن كفر انقطعت عنه النصرة؛ فاجعل طلبَ ولايةِ الله بالإيمانِ والطاعةِ والعملَ لما ينصرُ دأبك."}},{"n":36,"reflection":{"text":"«ولا طعام إلا من غسلين»، وليس له طعامٌ إلا من غسلينٍ (صديدِ أهلِ النارِ وما يسيل منهم)؛ ففي هذا بيانُ خبثِ طعامِ الشقيّ؛ فاحذر طعامَ أهلِ النار بالإيمانِ والعمل، فطعامُ النارِ خبيثٌ مؤذٍ، فاعمل لتنجو منه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من طعامِ النار، والعملُ للنجاةِ منه."},"action":{"text":"تأمّل خبثَ طعامِ الشقيّ: ولا طعامٌ، أي وليس له طعامٌ يأكله، إلا من غسلينٍ، أي من صديدِ أهلِ النارِ وقيحهم وما يسيل من أجسادهم، أو من شجرةٍ في النارِ خبيثة «ولا طعام إلا من غسلين»؛ ففي هذا بيانُ خبثِ طعامِ الشقيِّ في النار: صديدُ أهلِ النارِ وقيحهم؛ فطعامه أخبثُ طعام؛ فاحذر أنت طعامَ أهلِ النارِ بالإيمانِ والعملِ الصالح؛ ليس لهم طعامٌ إلا من ضريعٍ لا يُسمِن ولا يُغني من جوع؛ إنّ شجرةَ الزقّومِ طعامُ الأثيم؛ فطعامُ النارِ خبيثٌ مؤذٍ (زقّومٌ وضريعٌ وغسلين)؛ فاعمل للنجاةِ منه بالإيمانِ والطاعةِ والتقوى؛ فمن عمل للنجاةِ نجا، ومن أساء صار إليه؛ فاجعل الحذرَ من طعامِ النارِ والعملَ للنجاةِ منه دأبك."}},{"n":37,"reflection":{"text":"«لا يأكله إلا الخاطئون»: لا يأكل ذلك الغسلينَ إلا الخاطئون (المذنبون الكافرون المتعمّدون للخطأ)؛ ففي هذا بيانُ أنّ طعامَ النارِ للخاطئين؛ فاجتنب الخطايا لئلا تأكل طعامَ الخاطئين، فالخطايا سبيلُ العذاب، فاجتنبها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الخطايا، والحذرُ من عاقبةِ الخاطئين."},"action":{"text":"تأمّل أنّ طعامَ النارِ للخاطئين: لا يأكله (الغسلينَ) إلا الخاطئون، أي المذنبون الكافرون المصرّون على الخطايا المتعمّدون لها؛ فهو طعامُ أهلِ الخطايا والكفر «لا يأكله إلا الخاطئون»؛ ففي هذا بيانُ أنّ طعامَ النارِ (الغسلينَ) لا يأكله إلا الخاطئون المجرمون؛ فالخطايا الموجبةُ للكفرِ سبيلٌ إلى هذا الطعام؛ فاجتنب أنت الخطايا (الكفرَ والشركَ والمعاصيَ المصرَّ عليها) لئلا تكون من الخاطئين؛ إنهم كانوا قبل ذلك مترفين وكانوا يُصِرّون على الحنثِ العظيم؛ إنّ شجرةَ الزقّومِ طعامُ الأثيم؛ ولا يأكله إلا الخاطئون؛ فطعامُ النارِ للخاطئين المجرمين المصرّين؛ فاجتنب الخطايا، وتب منها، ولا تُصِرّ عليها؛ فمن اجتنب الخطايا وتاب نجا، ومن أصرّ عليها هلك؛ فاجعل اجتنابَ الخطايا والحذرَ من عاقبةِ الخاطئين دأبك."}}]},{"title":"القسمُ وتعظيمُ القرآنِ وتنزيهُ النبيِّ وختامُ السورة","range":[38,52],"theme":"القسمُ بالمشاهدِ والغائب على أنّ القرآن **«لقول رسول كريم»** لا شاعرٍ ولا كاهن، بل **«تنزيل من رب العالمين»**، وتقريرِ صدقِ النبيِّ ﷺ وأنه لو تقوّل على الله «لقطعنا منه الوتين»، وأنّ القرآنَ **«لتذكرة للمتقين»** و«حسرة على الكافرين» و**«لحق اليقين»**، وختمِ السورةِ **«فسبح باسم ربك العظيم»**","verses":[{"n":38,"reflection":{"text":"«فلا أقسم بما تبصرون»: أقسم الله بما تبصرون (من المخلوقاتِ المشاهدة)؛ ففي هذا قسمٌ بالمشاهداتِ تعظيمًا للمُقسَمِ عليه (القرآن)؛ فعظّم القرآنَ الذي أقسم الله على صدقه، فالقسمُ العظيمُ لأمرٍ عظيم، فأكرم القرآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ الذي أقسم الله على صدقه."},"action":{"text":"تأمّل القسمَ بالمشاهدات: فلا أقسم، أي أُقسِم («لا» صلةٌ للتوكيد)، وبما تبصرون، أي بجميعِ المخلوقاتِ التي تشاهدونها وترونها بأبصاركم «فلا أقسم بما تبصرون»؛ ففي هذا قسمٌ من الله بالمخلوقاتِ المشاهدة، تمهيدًا لتعظيمِ المُقسَمِ عليه (وهو القرآن)؛ فالقسمُ العظيمُ يدلّ على عظمةِ المُقسَمِ عليه؛ فعظّم أنت القرآنَ الذي أقسم الله على صدقه وشرفه؛ فلا أقسم بمواقعِ النجوم وإنه لقسمٌ لو تعلمون عظيم؛ فلا أقسم بالخنّس؛ فالله يُقسِم بمخلوقاتِه تنبيهًا على عظمتها وعظمةِ ما أقسم عليه؛ فأكرم القرآنَ وعظّمه وأقبل عليه؛ فمن عظّم القرآنَ أفلح، ومن استهان به خسر؛ فاجعل تعظيمَ القرآنِ الذي أقسم الله على صدقه دأبك."}},{"n":39,"reflection":{"text":"«وما لا تبصرون»، وبما لا تبصرون (من المخلوقاتِ الغائبةِ كالملائكةِ والغيب)؛ ففي هذا تمامُ القسمِ بالمشاهدِ والغائب؛ فأيقن بأنّ الله محيطٌ بالمشاهدِ والغائب، فعلمُ الله يشمل كلَّ شيء، فراقبه وأيقن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بإحاطةِ الله بالمشاهدِ والغائب، ومراقبتُه."},"action":{"text":"تأمّل تمامَ القسم: وما لا تبصرون، أي وأُقسِم بما لا تبصرونه من المخلوقاتِ الغائبةِ عن أبصاركم (كالملائكةِ والأرواحِ وعوالمِ الغيب) «وما لا تبصرون»؛ ففي هذا تمامُ القسمِ بجميعِ المخلوقات، ما يُبصَر منها وما لا يُبصَر، تعظيمًا للمُقسَمِ عليه؛ فقسمُ الله شاملٌ للمشاهدِ والغائب؛ فأيقن أنت بأنّ الله خالقٌ للمشاهدِ والغائب، محيطٌ بهما علمًا وقدرة؛ يعلم ما في السماواتِ والأرض؛ عالمُ الغيبِ والشهادة؛ وعنده مفاتحُ الغيبِ لا يعلمها إلا هو؛ فعلمُ الله وقدرتُه يشملان المشاهدَ والغائب؛ فراقبه، وأيقن بإحاطته، وعظّم القرآنَ المُقسَمَ عليه؛ فمن أيقن بإحاطةِ الله وراقبه استقام، ومن غفل ضلّ؛ فاجعل اليقينَ بإحاطةِ الله بالمشاهدِ والغائبِ ومراقبتَه دأبك."}},{"n":40,"reflection":{"text":"«إنه لقول رسول كريم»: إنّ القرآنَ لَقولُ رسولٍ كريمٍ (يبلّغه عن الله، وهو محمدٌ ﷺ)؛ ففي هذا تقريرُ أنّ القرآنَ وحيٌ يبلّغه الرسولُ الكريم؛ فعظّم القرآنَ الذي بلّغه الرسولُ الكريمُ عن الله، فالقرآنُ وحيٌ لا قولُ بشر، فأكرمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ الذي بلّغه الرسولُ الكريمُ عن الله."},"action":{"text":"تأمّل تقريرَ الوحي: إنه، أي المُقسَمَ عليه، القرآنَ، لَقولُ رسولٍ كريمٍ، أي لَقولٌ يبلّغه رسولٌ كريمٌ عن الله (وهو محمدٌ ﷺ)، فهو مُبلِّغٌ له عن ربّه لا مُختلِقٌ له «إنه لقول رسول كريم»؛ ففي هذا تقريرُ أنّ القرآنَ وحيٌ من الله يبلّغه الرسولُ الكريمُ محمدٌ ﷺ، وردٌّ على من زعم أنه شعرٌ أو كهانة؛ فالقرآنُ كلامُ الله بلّغه الرسول؛ فعظّم أنت القرآنَ الذي بلّغه الرسولُ الكريمُ عن الله؛ إنه لقولُ رسولٍ كريم ذي قوّةٍ عند ذي العرشِ مكين (في التكوير، عن جبريل)؛ وما ينطق عن الهوى إن هو إلا وحيٌ يوحى؛ فالقرآنُ وحيٌ يبلّغه الرسولُ الكريم، لا قولُ بشرٍ ولا اختلاق؛ فأكرمه، وعظّمه، واتّبعه؛ فمن عظّم القرآنَ واتّبعه اهتدى، ومن استهان به ضلّ؛ فاجعل تعظيمَ القرآنِ الذي بلّغه الرسولُ الكريمُ عن الله دأبك."}},{"n":41,"reflection":{"text":"«وما هو بقول شاعر قليلا ما تؤمنون»، وما القرآنُ بقولِ شاعرٍ، قليلًا ما تؤمنون؛ ففي هذا تنزيهُ القرآنِ عن أن يكون شعرًا؛ فنزّه القرآنَ عن مشابهةِ الشعرِ وأيقن أنه وحي، فالقرآنُ ليس شعرًا بل وحي، فأكرمه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ القرآنِ عن الشعر، واليقينُ بأنه وحي."},"action":{"text":"تأمّل تنزيهَ القرآنِ عن الشعر: وما هو (القرآنُ) بقولِ شاعرٍ، كما زعم بعضُ المشركين؛ فليس بشعرٍ ولا يشبهه في نظمه ومعانيه؛ قليلًا ما تؤمنون، أي إيمانكم قليلٌ أو منعدم «وما هو بقول شاعر قليلا ما تؤمنون»؛ ففي هذا تنزيهُ القرآنِ عن أن يكون قولَ شاعرٍ، وذمُّ المشركين على قلّةِ إيمانهم؛ فالقرآنُ ليس شعرًا بل وحيٌ مُعجِز؛ فنزّه أنت القرآنَ عن مشابهةِ الشعرِ وأقوالِ البشر، وأيقن أنه وحيٌ من الله؛ وما علّمناه الشعرَ وما ينبغي له إن هو إلا ذكرٌ وقرآنٌ مبين؛ أم يقولون شاعرٌ نتربّص به ريبَ المنون؛ فالقرآنُ ليس شعرًا ولا يشبهه، بل هو وحيٌ مُعجِز؛ فنزّهه عن ذلك، وأيقن بأنه كلامُ الله، وأكرمه؛ فمن نزّه القرآنَ وأيقن بأنه وحيٌ عظّمه، ومن شبّهه بالشعرِ ضلّ؛ فاجعل تنزيهَ القرآنِ عن الشعرِ واليقينَ بأنه وحيٌ دأبك."}},{"n":42,"reflection":{"text":"«ولا بقول كاهن قليلا ما تذكرون»، ولا هو بقولِ كاهنٍ، قليلًا ما تذكرون؛ ففي هذا تنزيهُ القرآنِ عن أن يكون كهانة؛ فنزّه القرآنَ عن مشابهةِ الكهانةِ وتذكّر أنه وحي، فالقرآنُ ليس كهانةً بل وحي، فأكرمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ القرآنِ عن الكهانة، والتذكّرُ بأنه وحي."},"action":{"text":"تأمّل تنزيهَ القرآنِ عن الكهانة: ولا بقولِ كاهنٍ، أي وليس القرآنُ بقولِ كاهنٍ (يتكهّن ويأتي بالسجعِ المُموَّه) كما زعم بعضهم؛ فليس كهانةً؛ قليلًا ما تذكرون، أي تذكّركم واتّعاظكم قليل «ولا بقول كاهن قليلا ما تذكرون»؛ ففي هذا تنزيهُ القرآنِ عن أن يكون كهانةً، وذمُّ المشركين على قلّةِ تذكّرهم؛ فالقرآنُ ليس كهانةً بل وحيٌ من الله؛ فنزّه أنت القرآنَ عن مشابهةِ الكهانةِ وأقوالِ الكهّان، وتذكّر أنه وحيٌ حقّ؛ وما تنزّلت به الشياطين وما ينبغي لهم وما يستطيعون؛ إنه لقولٌ فصل وما هو بالهزل؛ فالقرآنُ منزّهٌ عن الشعرِ والكهانةِ وكلِّ باطل، وهو وحيٌ مُحكَم؛ فنزّهه، وتذكّر أنه كلامُ الله، وأكرمه، واتّعظ به؛ فمن نزّه القرآنَ وتذكّر به اهتدى، ومن شبّهه بالكهانةِ ضلّ؛ فاجعل تنزيهَ القرآنِ عن الكهانةِ والتذكّرَ بأنه وحيٌ دأبك."}},{"n":43,"reflection":{"text":"«تنزيل من رب العالمين»: هو تنزيلٌ من ربِّ العالمين؛ ففي هذا تقريرُ مصدرِ القرآنِ الأعلى؛ فعظّم قرآنًا نزل من ربِّ العالمين، فالقرآنُ كلامُ ربِّ العالمين، فأكرمه واتّبعه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ لأنه تنزيلٌ من ربِّ العالمين، واتّباعُه."},"action":{"text":"تأمّل مصدرَ القرآن: هو تنزيلٌ، أي منزّلٌ، من ربِّ العالمين، خالقِ الخلقِ ومربّيهم ومدبّرِ أمرهم؛ فمصدره أعلى مصدرٍ وأشرفه «تنزيل من رب العالمين»؛ ففي هذا تقريرُ مصدرِ القرآنِ الأعلى: أنه كلامُ ربِّ العالمين، نزل من عنده على رسوله، فليس شعرًا ولا كهانةً ولا قولَ بشر؛ فعظّم أنت قرآنًا نزل من ربِّ العالمين، فهو كلامه سبحانه؛ وإنه لتنزيلُ ربِّ العالمين نزل به الروحُ الأمين؛ تنزيلُ الكتابِ من الله العزيزِ الحكيم؛ لا يأتيه الباطلُ من بين يديه ولا من خلفه تنزيلٌ من حكيمٍ حميد؛ فالقرآنُ كلامُ ربِّ العالمين يستحقّ غايةَ التعظيمِ والاتّباع؛ فأكرمه، واتّبعه، واعمل به، وتدبّره؛ فمن عظّمه واتّبعه اهتدى، ومن أعرض عنه ضلّ؛ فاجعل تعظيمَ القرآنِ لأنه تنزيلٌ من ربِّ العالمين واتّباعَه دأبك."}},{"n":44,"reflection":{"text":"«ولو تقول علينا بعض الأقاويل»، ولو اختلق محمدٌ علينا بعضَ الأقوال (فنسبها إلينا كذبًا)؛ ففي هذا تقريرُ صدقِ النبيِّ ﷺ وأنه لا يتقوّل على الله؛ فأيقن بصدقِ النبيِّ ﷺ في تبليغه، فالنبيُّ ﷺ صادقٌ لا يتقوّل، فصدّقه واتّبعه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بصدقِ النبيِّ ﷺ في التبليغ، وتصديقُه."},"action":{"text":"تأمّل تقريرَ صدقِ النبيّ: ولو تقوّل علينا، أي ولو اختلق محمدٌ علينا وتكلّف، بعضَ الأقاويلِ، أي بعضَ الأقوالِ فنسبها إلينا كذبًا ولم نقلها؛ فرضًا وتقديرًا «ولو تقول علينا بعض الأقاويل»؛ ففي هذا تقريرُ صدقِ النبيِّ ﷺ في تبليغه عن الله، وأنه لو تقوّل عليه، وحاشاه، لعاجله بالعقوبة (كما في الآيةِ بعدها)؛ فالنبيُّ ﷺ صادقٌ لا يتقوّل على الله؛ فأيقن أنت بصدقِ النبيِّ ﷺ في كلِّ ما بلّغه عن الله؛ وما ينطق عن الهوى إن هو إلا وحيٌ يوحى؛ قل ما يكون لي أن أبدّله من تلقاءِ نفسي؛ ولو تقوّل علينا بعضَ الأقاويل؛ فالنبيُّ ﷺ صادقٌ أمينٌ لا يتقوّل على الله، وما بلّغه فهو وحيٌ حقّ؛ فصدّقه، واتّبعه، وأطعه؛ فمن صدّق النبيَّ واتّبعه اهتدى، ومن كذّبه ضلّ؛ فاجعل اليقينَ بصدقِ النبيِّ ﷺ في التبليغِ وتصديقَه دأبك."}},{"n":45,"reflection":{"text":"«لأخذنا منه باليمين»: لأخذنا منه بالقوّةِ والقدرة (انتقامًا)؛ ففي هذا بيانُ شدّةِ عقوبةِ من يتقوّل على الله؛ فاحذر القولَ على الله بلا علمٍ فإنّ عقوبته شديدة، فالتقوّلُ على الله جريمة، فقل الحقَّ عن علم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التقوّلِ على الله، وقولُ الحقِّ عن علم."},"action":{"text":"تأمّل شدّةَ العقوبة: لأخذنا منه باليمينِ، أي لأخذناه بالقوّةِ والقدرةِ والغلبة (واليمينُ رمزُ القوّة)، أو لأخذنا بيمينه انتقامًا؛ عقوبةً له لو تقوّل علينا «لأخذنا منه باليمين»؛ ففي هذا بيانُ شدّةِ عقوبةِ من يتقوّل على الله، ولو كان الرسولَ نفسه، على سبيلِ الفرض؛ فالتقوّلُ على الله جريمةٌ عقوبتها شديدة؛ فاحذر أنت القولَ على الله بلا علم، أو نسبةَ ما لم يقله إليه؛ ومن أظلمُ ممّن افترى على الله كذبًا؛ ولا تقولوا لما تصف ألسنتكم الكذبَ هذا حلالٌ وهذا حرامٌ لتفتروا على الله الكذب؛ فالتقوّلُ على الله (بالكذبِ عليه، أو القولِ بلا علم) جريمةٌ عقوبتها شديدة؛ فقل الحقَّ عن علم، ولا تقل على الله بلا علم، ولا تفترِ عليه؛ فمن قال الحقَّ عن علمٍ سلم، ومن تقوّل على الله عُوقِب؛ فاجعل الحذرَ من التقوّلِ على الله وقولَ الحقِّ عن علمٍ دأبك."}},{"n":46,"reflection":{"text":"«ثم لقطعنا منه الوتين»: ثم لقطعنا منه نياطَ قلبه (الوتينَ) فيهلك؛ ففي هذا تمامُ بيانِ عقوبةِ المتقوّلِ على الله؛ فاحذر أشدَّ الحذرِ من الكذبِ على الله، فالكذبُ على الله سبيلُ الهلاك، فاصدق فيه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ الشديدُ من الكذبِ على الله، والصدقُ فيه."},"action":{"text":"تأمّل تمامَ العقوبة: ثم لقطعنا منه الوتينَ، أي لقطعنا نياطَ قلبه (الوتينُ عرقٌ في القلبِ إذا انقطع مات صاحبه) فيهلك ويموت؛ عقوبةً لو تقوّل على الله «ثم لقطعنا منه الوتين»؛ ففي هذا تمامُ بيانِ شدّةِ عقوبةِ من يتقوّل على الله: الأخذُ بقوّةٍ ثم قطعُ الوتينِ والإهلاك؛ فالكذبُ على الله سبيلُ الهلاك؛ فاحذر أنت أشدَّ الحذرِ من الكذبِ على الله، أو القولِ عليه بلا علم؛ ويقولون على الله الكذبَ وهم يعلمون؛ إنّ الذين يفترون على الله الكذبَ لا يفلحون؛ فالكذبُ على الله والتقوّلُ عليه سبيلُ الهلاكِ والعذاب؛ فاصدق فيما تنسبه إلى الله، ولا تكذب عليه، ولا تقل بلا علم؛ فمن صدق وتحرّى سلم، ومن كذب على الله هلك؛ فاجعل الحذرَ الشديدَ من الكذبِ على الله والصدقَ فيه دأبك."}},{"n":47,"reflection":{"text":"«فما منكم من أحد عنه حاجزين»: فما منكم من أحدٍ يحجز عنه العقوبةَ ويمنعها؛ ففي هذا بيانُ نفوذِ قدرةِ الله وأنه لا مانعَ منه؛ فأيقن أنه لا مانعَ من عقوبةِ الله فاتّقه، فلا حاجزَ من الله، فاتّقِ عقوبته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنه لا مانعَ من عقوبةِ الله، وتقواه."},"action":{"text":"تأمّل نفوذَ قدرةِ الله: فما منكم من أحدٍ، كائنًا من كان، عنه حاجزين، أي يحجزون عنه العقوبةَ ويمنعونها ويدفعونها؛ فلو عاقب الله أحدًا لم يمنعه منه أحد «فما منكم من أحد عنه حاجزين»؛ ففي هذا بيانُ نفوذِ قدرةِ الله، وأنه لا أحدَ يمنع عقوبته أو يحجزها عمّن أرادها؛ فلا مانعَ من الله؛ فأيقن أنت بأنه لا مانعَ من عقوبةِ الله ولا حاجز، فاتّقه واحذر عقوبته؛ فمن ينصرنا من بأسِ الله إن جاءنا؛ وما لهم من دونِ الله من وليٍّ ولا واق؛ يقول هل من مفرّ كلّا لا وزر؛ فلا حاجزَ من عقوبةِ الله ولا مانع؛ فاتّقِ الله، واحذر عقوبته، واعمل بطاعته؛ فمن اتّقى الله نجا، ومن أمِن مكره أُخِذ؛ فاجعل اليقينَ بأنه لا مانعَ من عقوبةِ الله وتقواه دأبك."}},{"n":48,"reflection":{"text":"«وإنه لتذكرة للمتقين»، وإنّ القرآنَ لَعظةٌ وتذكرةٌ للمتّقين (المنتفعين به)؛ ففي هذا بيانُ أنّ المنتفعَ بالقرآنِ هم المتّقون؛ فاتّقِ الله لتنتفع بالقرآنِ وتتذكّر به، فالقرآنُ تذكرةٌ للمتّقين، فاتّقِ لتنتفع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التقوى للانتفاعِ بالقرآنِ والتذكّرِ به."},"action":{"text":"تأمّل أنّ القرآنَ تذكرةٌ للمتّقين: وإنه (القرآنَ) لَتذكرةٌ، أي عظةٌ وتذكيرٌ وشرفٌ، للمتّقين (الذين يخافون الله فينتفعون به ويتّعظون)؛ فهم المنتفعون به دون غيرهم «وإنه لتذكرة للمتقين»؛ ففي هذا بيانُ أنّ القرآنَ تذكرةٌ وعظةٌ ينتفع بها المتّقون خاصّة؛ فالتقوى شرطُ الانتفاعِ بالقرآن؛ فاتّقِ أنت الله لتنتفع بالقرآنِ وتتذكّر به وتتّعظ؛ هدًى للمتّقين؛ ذلك الكتابُ لا ريبَ فيه هدًى للمتّقين؛ إنما تُنذِر من اتّبع الذكرَ وخشيَ الرحمن بالغيب؛ فالقرآنُ تذكرةٌ ينتفع بها المتّقون؛ فاتّقِ الله، وتدبّر القرآن، واتّعظ به، واعمل بمقتضاه؛ فمن اتّقى وانتفع بالقرآنِ اهتدى، ومن أعرض حُرِم؛ فاجعل التقوى للانتفاعِ بالقرآنِ والتذكّرِ به دأبك."}},{"n":49,"reflection":{"text":"«وإنا لنعلم أن منكم مكذبين»، وإنا لنعلم أنّ منكم مكذّبين بالقرآن؛ ففي هذا بيانُ علمِ الله بالمكذّبين ووعيدهم؛ فاحذر أن تكون من المكذّبين فالله يعلمهم، فالتكذيبُ بالقرآنِ معلومٌ لله، فصدّق به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ بالقرآن، والحذرُ من التكذيبِ به."},"action":{"text":"تأمّل علمَ الله بالمكذّبين: وإنا لنعلم أنّ منكم، أيها الناس، مكذّبين بالقرآنِ لا يؤمنون به؛ فالله عالمٌ بهم مُجازيهم على تكذيبهم «وإنا لنعلم أن منكم مكذبين»؛ ففي هذا بيانُ علمِ الله بالمكذّبين بالقرآن، وفيه وعيدٌ لهم؛ فتكذيبهم معلومٌ لله لا يخفى عليه؛ فاحذر أنت أن تكون من المكذّبين بالقرآن، فإنّ الله يعلمهم ويجازيهم؛ والله بما تعملون بصير؛ وإنا لنعلم أن منكم مكذّبين؛ إنّ الذين كفروا بالذكرِ لمّا جاءهم؛ فالتكذيبُ بالقرآنِ معلومٌ لله، وعاقبته الحسرةُ والعذاب؛ فصدّق بالقرآن، وآمن به، واعمل بمقتضاه، ولا تكذّب؛ فمن صدّق بالقرآنِ نجا، ومن كذّب به خسر؛ فاجعل التصديقَ بالقرآنِ والحذرَ من التكذيبِ به دأبك."}},{"n":50,"reflection":{"text":"«وإنه لحسرة على الكافرين»، وإنّ القرآنَ لَحسرةٌ على الكافرين (يومَ القيامةِ إذ لم يؤمنوا به)؛ ففي هذا بيانُ أنّ القرآنَ حسرةٌ على من كفر به؛ فآمن بالقرآنِ لئلا يكون حسرةً عليك، فتكذيبُ القرآنِ حسرة، فآمن به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بالقرآن، والحذرُ من أن يكون حسرة."},"action":{"text":"تأمّل أنّ القرآنَ حسرةٌ على الكافرين: وإنه (القرآنَ) لَحسرةٌ على الكافرين، أي إنّ القرآنَ الذي كذّبوا به يكون حسرةً وندامةً عليهم يومَ القيامة، حين يرون ثوابَ المؤمنين به وعقابَ المكذّبين، فيتحسّرون على تكذيبهم «وإنه لحسرة على الكافرين»؛ ففي هذا بيانُ أنّ القرآنَ الذي هو تذكرةٌ للمتّقين يكون حسرةً على الكافرين المكذّبين به يومَ القيامة؛ فتكذيبُ القرآنِ يورث الحسرة؛ فآمن أنت بالقرآنِ واعمل به لئلا يكون حسرةً عليك؛ يا حسرةً على العباد؛ أن تقول نفسٌ يا حسرتى على ما فرّطتُ في جنبِ الله؛ وإنه لحسرةٌ على الكافرين؛ فالقرآنُ حسرةٌ على من كفر به وفرّط فيه؛ فآمن به، وتدبّره، واعمل بمقتضاه، لئلا تتحسّر يومَ القيامة؛ فمن آمن بالقرآنِ وعمل به فاز، ومن كذّب به تحسّر؛ فاجعل الإيمانَ بالقرآنِ والحذرَ من أن يكون حسرةً دأبك."}},{"n":51,"reflection":{"text":"«وإنه لحق اليقين»، وإنّ القرآنَ لَحقُّ اليقينِ (الثابتُ المتيقَّنُ الذي لا شكَّ فيه)؛ ففي هذا تأكيدُ أنّ القرآنَ حقٌّ متيقَّن؛ فأيقن بأنّ القرآنَ حقُّ اليقينِ واعمل به، فالقرآنُ حقٌّ لا ريبَ فيه، فأيقن واعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ الجازمُ بأنّ القرآنَ حقّ، والعملُ به."},"action":{"text":"تأمّل تأكيدَ حقّيّةِ القرآن: وإنه (القرآنَ) لَحقُّ اليقينِ، أي الحقُّ الثابتُ المتيقَّنُ الذي لا شكَّ فيه ولا ريب، أعلى مراتبِ اليقين؛ فهو الحقُّ حقًّا «وإنه لحق اليقين»؛ ففي هذا تأكيدُ أنّ القرآنَ حقٌّ متيقَّنٌ لا مِريةَ فيه، وأنّ ما فيه من الأخبارِ والأحكامِ حقٌّ ثابت؛ فالقرآنُ حقُّ اليقين؛ فأيقن أنت بأنّ القرآنَ حقُّ اليقينِ يقينًا جازمًا، واعمل به؛ إنّ هذا لهو حقُّ اليقين؛ لا ريبَ فيه؛ وإنه لحقُّ اليقين؛ الحقُّ من ربّك فلا تكوننّ من الممترين؛ فالقرآنُ حقٌّ متيقَّنٌ لا شكَّ فيه، كلامُ الله الصادق؛ فأيقن به يقينًا جازمًا، واعمل بمقتضاه، ولا تشكّ فيه؛ فمن أيقن بالقرآنِ وعمل به نجا، ومن شكّ فيه أو أعرض خسر؛ فاجعل اليقينَ الجازمَ بأنّ القرآنَ حقٌّ والعملَ به دأبك."}},{"n":52,"reflection":{"text":"«فسبح باسم ربك العظيم»: فنزّه ربَّك العظيمَ باسمه، وسبّحه تعظيمًا وشكرًا؛ ففي هذا ختمُ السورةِ بالأمرِ بالتسبيح؛ فسبّح ربَّك العظيمَ وعظّمه، فالتسبيحُ حقُّ العظيمِ على عبده، فسبّح واعبده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تسبيحُ الله العظيمِ وتعظيمُه، والعبادةُ له."},"action":{"text":"تأمّل ختمَ السورةِ بالتسبيح: فسبِّح، أيها الرسولُ ومن تبعك، باسمِ ربّك العظيمِ، أي نزّه الله العظيمَ عمّا لا يليق به، واذكر اسمه مُعظِّمًا مُنزِّهًا، تعظيمًا له وشكرًا على نعمه (منها القرآن) وتنزيهًا له عمّا نسبه إليه المكذّبون «فسبح باسم ربك العظيم»؛ ففي هذا (وهو ختامُ السورة) ختمُ السورةِ بالأمرِ بتسبيحِ الله العظيمِ وتنزيهه وتعظيمه، بعد تقريرِ القيامةِ وتعظيمِ القرآن؛ فحقُّ من هذه عظمتُه أن يُسبَّح ويُعظَّم؛ فسبّح أنت ربَّك العظيمَ ونزّهه وعظّمه واعبده؛ فسبّح بحمدِ ربّك وكن من الساجدين؛ سبّح اسمَ ربّك الأعلى؛ فسبّح بحمدِ ربّك حين تقوم؛ فالتسبيحُ حقُّ الربِّ العظيمِ على عبده، تعظيمًا وشكرًا وعبادة؛ فسبّحه، وعظّمه، واعبده وحده؛ فمن سبّح الله وعظّمه وعبده أفلح، ومن غفل خسر؛ فاجعل تسبيحَ الله العظيمِ وتعظيمَه والعبادةَ له دأبك."}}]}],"coverage":{"covered":52,"total":52}};
